    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N;
    cin >> N;

    if (N == 1) {
        cout << 3 << '\n';
        return 0;
    }

    long long index = N - 2;
    long long k = index / 3 + 1;
    long long remainder = index % 3;

    long long answer = 4 * k + (remainder == 0 ? 1 : remainder == 1 ? 3 : 4);
