#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 N;
    cin >> N;

    auto countSuitable = [](int64 x) {
        int64 odd = max<int64>(0, (x + 1) / 2 - 1);
        int64 divisibleByFour = max<int64>(0, x / 4 - 1);
        return odd + divisibleByFour;
    };

    int64 low = 1, high = 2000000000LL;
    while (low < high) {
        int64 mid = low + (high - low) / 2;
        if (countSuitable(mid) >= N)
            high = mid;
        else
            low = mid + 1;
    }

    cout << low << '\n';
    return 0;
}

